const fdsBonusView={sku:'xr_500',paidBoxes:null,bonusBoxes:null,referenceBoxCost:null,bonusSaleUnitPrice:null};
const bonusMoney=value=>value==null?'—':new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN',minimumFractionDigits:2,maximumFractionDigits:2}).format(value);
const bonusPrecise=value=>value==null?'—':new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN',minimumFractionDigits:4,maximumFractionDigits:4}).format(value);
const bonusPercent=value=>value==null?'—':new Intl.NumberFormat('es-PE',{style:'percent',minimumFractionDigits:1,maximumFractionDigits:1}).format(value);

function renderFdsBonus(){
  const data=state.fdsBonus, skus=data.skus,bonusSku=skus.find(row=>row.key===data.promotion.bonusSku);
  if(fdsBonusView.paidBoxes==null){
    fdsBonusView.paidBoxes=data.promotion.paidBoxes;
    fdsBonusView.bonusBoxes=data.promotion.bonusBoxes;
    fdsBonusView.referenceBoxCost=bonusSku.paidBoxCost;
    fdsBonusView.bonusSaleUnitPrice=bonusSku.saleUnitPrice;
  }
  const settings={...fdsBonusView,nominalBonusCostPerBox:data.meta.nominalBonusCostPerBox};
  const selected=skus.find(row=>row.key===fdsBonusView.sku)||skus[0];
  const example=GlucophageBonus.calculate(selected,bonusSku,settings);
  const rows=skus.map(row=>({row,result:GlucophageBonus.calculate(row,bonusSku,settings)}));
  content.innerHTML=`<div class="view"><div class="section-head"><div><p class="eyebrow">FDS · BONIFICACIÓN GLUCOPHAGE</p><h2>Valor de las cajas XR 1000 bonificadas</h2><p>Modelo por pedido: cualquier presentación comprada genera cajas XR 1000 de regalo según la relación indicada.</p></div><span class="pill">Facturas hasta ${esc(data.meta.invoiceThrough)}</span></div>
    <div class="cost-note"><b>Lectura del margen:</b> el costo de reposición de XR 1000 se distribuye entre las cajas compradas para analizar la promoción; esta simulación no actualiza la contabilidad ni la BD madre. El margen conjunto usa el dinero pagado en la factura y el ingreso de vender todas las cajas, sin contar dos veces el regalo. Cada fila supone que todas las cajas pagadas son de esa presentación; en un pedido mixto el crédito por caja es igual, pero el margen total depende de la mezcla. Los precios de venta son de lista del maestro del ${esc(data.meta.productMasterDate)}, no ventas efectivamente cobradas.</div>
    <div class="analytics-filters"><label>Presentación del ejemplo<select id="bonusSku">${skus.map(row=>`<option value="${esc(row.key)}" ${row.key===selected.key?'selected':''}>${esc(row.label)}</option>`).join('')}</select></label><label>Cajas compradas<input id="bonusPaid" type="number" min="1" step="1" value="${esc(fdsBonusView.paidBoxes)}"></label><label>Cajas XR 1000 bonificadas<input id="bonusFree" type="number" min="0" step="1" value="${esc(fdsBonusView.bonusBoxes)}"></label><label>Costo referencia XR 1000 / caja (S/)<input id="bonusReference" type="number" min="0" step="0.01" value="${esc(fdsBonusView.referenceBoxCost)}"></label><label>Venta XR 1000 / comprimido (S/)<input id="bonusSale" type="number" min="0" step="0.01" value="${esc(fdsBonusView.bonusSaleUnitPrice)}"></label></div>
    ${example?`<section class="kpis">${kpi('S/',bonusMoney(example.bonusReferenceValue),'Valor de reposición del regalo',`${fdsBonusView.bonusBoxes} cajas XR 1000`)}${kpi('↓',bonusMoney(example.creditPerPaidBox),'Crédito atribuido por caja pagada','valor de costo distribuido')}${kpi('＋',bonusMoney(example.bonusSaleRevenue),'Venta potencial del regalo','si se vende todo a lista')}${kpi('%',bonusPercent(example.bundleMargin),'Margen del pedido completo',`${esc(selected.label)} + XR 1000 bonificado`)}</section>`:'<p class="import-error" role="alert">Indica cantidades y precios válidos para calcular.</p>'}
    <div class="grid-2"><article class="card"><div class="card-header"><div><h3>Ejemplo: ${esc(selected.label)}</h3><p>${esc(fdsBonusView.paidBoxes)} cajas pagadas + ${esc(fdsBonusView.bonusBoxes)} cajas XR 1000 bonificadas</p></div></div>${example?`<p>Costo pagado por caja: <b>${bonusMoney(selected.paidBoxCost)}</b> · ${selected.unitsPerBox} unidades por caja.</p><p>Costo atribuido tras valorar el regalo: <b>${bonusPrecise(example.attributedCostPerUnit)}</b> por unidad de ${esc(selected.label)}.</p><p>Ingreso potencial total: <b>${bonusMoney(example.bundleRevenue)}</b> · costo pagado: <b>${bonusMoney(example.bundleCost)}</b>.</p><p>Utilidad potencial del conjunto: <b>${bonusMoney(example.bundleProfit)}</b>. El regalo aporta <b>${bonusMoney(example.bonusCashContribution)}</b> de ingreso menos su cobro nominal de ${bonusMoney(data.meta.nominalBonusCostPerBox)} por caja.</p>`:''}</article><article class="card"><div class="card-header"><div><h3>Fuente del valor</h3><p>Compra pagada y precio de venta de XR 1000</p></div></div><p>Última compra pagada XR 1000: <b>${bonusMoney(bonusSku.paidBoxCost)} por caja</b> de ${bonusSku.unitsPerBox} comprimidos · ${esc(bonusSku.invoice)} · ${dateFmt(bonusSku.invoiceDate)}.</p><p>Precio de lista: <b>${bonusMoney(bonusSku.saleUnitPrice)} por comprimido</b> (${bonusMoney(bonusSku.saleUnitPrice*bonusSku.unitsPerBox)} por caja).</p><p>Las cajas bonificadas aparecen en factura a <b>${bonusMoney(data.meta.nominalBonusCostPerBox)}</b> cada una. Ese importe no representa su costo de reposición.</p></article></div>
    <article class="card" style="margin-top:16px"><div class="card-header"><div><h3>Impacto por presentación comprada</h3><p>El margen del conjunto considera la venta de ${esc(fdsBonusView.paidBoxes)} cajas compradas y ${esc(fdsBonusView.bonusBoxes)} cajas XR 1000 bonificadas.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Producto comprado</th><th>Última factura pagada</th><th>Costo / caja</th><th>Costo / unidad</th><th>Crédito / caja</th><th>Costo atribuido / unidad</th><th>Venta lista / unidad</th><th>Margen sin regalo</th><th>Margen del conjunto</th></tr></thead><tbody>${rows.map(({row,result})=>`<tr><td><b>${esc(row.label)}</b><small class="cell-note">${esc(row.gtin)} · caja x ${row.unitsPerBox}</small></td><td>${esc(row.invoice)}<small class="cell-note">${dateFmt(row.invoiceDate)}</small></td><td class="numeric">${bonusMoney(row.paidBoxCost)}</td><td class="numeric">${bonusPrecise(result?.grossCostPerUnit)}</td><td class="numeric">${bonusMoney(result?.creditPerPaidBox)}</td><td class="numeric">${bonusPrecise(result?.attributedCostPerUnit)}</td><td class="numeric">${bonusMoney(row.saleUnitPrice)}</td><td class="numeric">${bonusPercent(result?.baseMargin)}</td><td class="numeric"><b>${bonusPercent(result?.bundleMargin)}</b></td></tr>`).join('')}</tbody></table></div></article>
    <article class="card" style="margin-top:16px"><div class="card-header"><div><h3>Bonificación observada en facturas</h3><p>Los pedidos históricos muestran relaciones distintas. El cálculo superior representa el acuerdo 12:4 indicado para pedidos actuales.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Factura FDS</th><th>Fecha</th><th>Cajas Glucophage pagadas</th><th>Cajas XR 1000 bonificadas</th><th>Por cada 12 pagadas</th><th>Fuente</th></tr></thead><tbody>${data.observations.map(row=>`<tr><td>${esc(row.invoice)}</td><td>${dateFmt(row.date)}</td><td class="numeric">${quantity(row.paidBoxes)}</td><td class="numeric">${quantity(row.bonusBoxes)}</td><td class="numeric">${quantity(row.bonusBoxes/row.paidBoxes*12)}</td><td>${esc(row.source)}</td></tr>`).join('')}</tbody></table></div></article></div>`;
  $('#bonusSku').onchange=event=>{fdsBonusView.sku=event.target.value;renderFdsBonus()};
  for(const [id,key] of [['bonusPaid','paidBoxes'],['bonusFree','bonusBoxes'],['bonusReference','referenceBoxCost'],['bonusSale','bonusSaleUnitPrice']]){
    $('#'+id).onchange=event=>{fdsBonusView[key]=Number(event.target.value);renderFdsBonus()};
  }
}
